def _execute_source_capture(
    *,
    context: CaptureContext,
    evidence: GitHubEvidence,
    capture_function: Callable[[CaptureContext, GitHubEvidence], None],
    run_root: Path,
    execution_started_at_utc: str,
) -> None:
    """Run one source under a total, non-reflective finalization boundary."""

    safe_error: DiscoveryExecutionError | None = None
    try:
        capture_function(context, evidence)
        context.finalize(status="CAPTURE_COMPLETE", evidence=evidence)
    except BaseException as error:
        safe_error, _, _ = context.finalize_failed(evidence=evidence, error=error)
        _write_abort(
            run_root=run_root,
            source_id_value=context.source_id,
            error=safe_error,
            started_at_utc=execution_started_at_utc,
        )
    if safe_error is not None:
        raise safe_error


@contextmanager
def _catchable_source_signal_boundary():
    """Translate main-thread SIGINT/SIGTERM into terminal source failure."""

    if threading.current_thread() is not threading.main_thread():
        yield
        return
    candidates = (
        getattr(signal, "SIGINT", None),
        getattr(signal, "SIGTERM", None),
    )
    catchable = tuple(candidate for candidate in candidates if candidate is not None)
    previous = {candidate: signal.getsignal(candidate) for candidate in catchable}

    def interrupt(_signum: int, _frame: Any) -> None:
        for candidate in catchable:
            signal.signal(candidate, signal.SIG_IGN)
        raise KeyboardInterrupt("catchable discovery termination signal")

    try:
        for candidate in catchable:
            signal.signal(candidate, interrupt)
        yield
    finally:
        for candidate, handler in previous.items():
            signal.signal(candidate, handler)


def execute_discovery(
    *, project_root: Path, run_root: Path, token_path: Path
) -> dict[str, Any]:
    """Capture all frozen sources, then materialize and freeze the raw pool."""

    plan_path = run_root / "execution-plan.json"
    execution_plan = _load_json_object(plan_path)
    validate_execution_preflight(
        project_root=project_root, run_root=run_root, execution_plan=execution_plan
    )
    token = read_token_file(token_path)
    started_at = utc_now()
    start_record = {
        "schema": "candidate-discovery-execution-start-v0.3",
        "protocol_version": PROTOCOL_VERSION,
        "implementation_commit": execution_plan["implementation_commit"],
        "operational_amendment_version": OPERATIONAL_AMENDMENT_VERSION,
        "operational_amendment_sha256": OPERATIONAL_AMENDMENT_SHA256,
        "capture_reuse": "NONE_FRESH_CAPTURE",
        "predecessor_failed_run_id": PREDECESSOR_FAILED_RUN_ID,
        "predecessor_stopped_run_ids": list(PREDECESSOR_STOPPED_RUN_IDS),
        "execution_start_utc": started_at,
        "credential_preflight": {
            "configured": True,
            "value_recorded": False,
            "authorization_header_recorded": False,
        },
        "experiment_accessed": False,
        "treatment_results_consulted": False,
    }
    start_path = run_root / "execution-start.json"
    start_digest = write_new_json(start_path, start_record)
    write_hash_sidecar(start_path, start_digest)
    search_spec = _load_json_object(
        project_root
        / "benchmark-selection/discovery/prospective-v0.2/"
        "trust-boundary-issues-prs.json"
    )
    source_definitions: list[
        tuple[str, str, Mapping[str, str], Callable[[CaptureContext, GitHubEvidence], None]]
    ] = [
        (
            BUGSINPY_SOURCE_ID,
            "REPOSITORY_REPAIR_BENCHMARK",
            {"kind": "GIT_COMMIT", "value": BUGSINPY_REVISION},
            capture_bugsinpy,
        ),
        (
            ADVISORY_SOURCE_ID,
            "SECURITY_ADVISORY_REPAIR",
            {"kind": "GIT_COMMIT", "value": ADVISORY_REVISION},
            capture_advisories,
        ),
        (
            SEARCH_SOURCE_ID,
            "TRUST_BOUNDARY_ISSUE_PR_SEARCH",
            {"kind": "FROZEN_QUERY_SPECIFICATION", "value": SEARCH_SPEC_SHA256},
            lambda context, evidence: capture_searches(
                context, evidence, search_spec=search_spec
            ),
        ),
    ]
    try:
        for source_id_value, source_kind, revision, capture_function in source_definitions:
            context = CaptureContext.create(
                run_root=run_root,
                source_id=source_id_value,
                source_kind=source_kind,
                source_revision=revision,
                token=token,
            )
            evidence = GitHubEvidence(context)
            with _catchable_source_signal_boundary():
                _execute_source_capture(
                    context=context,
                    evidence=evidence,
                    capture_function=capture_function,
                    run_root=run_root,
                    execution_started_at_utc=started_at,
                )
    finally:
        token = ""
    return materialize_run(
        project_root=project_root,
        run_root=run_root,
        execution_started_at_utc=started_at,
    )


def _forbidden_keys(value: Any) -> set[str]:
    found: set[str] = set()
    if isinstance(value, Mapping):
        for key, nested in value.items():
            if str(key) in FORBIDDEN_DISCOVERY_ASSIGNMENTS:
                found.add(str(key))
            found.update(_forbidden_keys(nested))
    elif isinstance(value, list):
        for nested in value:
            found.update(_forbidden_keys(nested))
    return found


